INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','ed-ing-adjectives','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"ed-ing-adjectives","title":"Adjectives ending in -ed and -ing","level":"A2","order":22,"summary":"Distinguish an experienced feeling from something that causes that feeling.","learningGoals":["The experienced feeling","The cause of the feeling","Connect cause and effect"],"guidance":"Read the rules and examples, then try a 20-question session. Explain why your chosen form fits the context and revisit any missed skill.","rules":[{"title":"The experienced feeling","explanation":"In these adjective pairs, the -ed form describes how someone feels. Context identifies the experiencer.","examples":["The climbers felt exhausted.","The children seemed delighted."]},{"title":"The cause of the feeling","explanation":"The -ing form describes what produces the feeling. A person can also cause a feeling, so do not use a people-versus-things shortcut.","examples":["The climb was exhausting.","An entertaining storyteller can hold our attention."]},{"title":"Connect cause and effect","explanation":"Read who experiences the emotion and what causes it. The two forms belong to the same adjective family but have different roles.","examples":["A confusing instruction leaves a reader confused.","An exciting event leaves spectators excited."]}],"tips":["Check both the meaning and the form before answering.","Use the explanation to understand a mistake before moving on.","A practice result is feedback, not an official language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-ed-ing-adjectives"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment."},"quizItems":[{"id":"ea60c683-137e-5298-aa03-9f98ce17ed3a","topicSlug":"ed-ing-adjectives","level":"A2","prompt":"Describe the feeling in the “bore” family: After the repetitive safety video, the trainees felt ____.","choices":[{"id":"A","text":"bore"},{"id":"B","text":"bores"},{"id":"C","text":"bored"},{"id":"D","text":"boring"}],"answerId":"C","hint":"In these adjective pairs, the -ed form describes how someone feels. Context identifies the experiencer. Focus on **experienced feeling** in this question.","explanation":"Bored describes the feeling experienced by the trainees; boring describes its cause.","keywords":[],"source":"seed","skill":"experienced-feeling","contextKey":"emotion-1","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-ed-ing-adjectives"],"version":"foundations-2026-09-v2","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"2aac133deb51723dd631f8351a60312ced6a29e98a07e146be2cb2c98a3e6885","teaching":{"steps":["Identify what the question tests: **experienced feeling**. In these adjective pairs, the -ed form describes how someone feels. Context identifies the experiencer.","Bored describes the feeling experienced by the trainees; boring describes its cause.","Choose **bored**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"This is not the adjective form for the role asked about: the person experiencing the feeling. Bored describes the feeling experienced by the trainees; boring describes its cause.","B":"This is not the adjective form for the role asked about: the person experiencing the feeling. Bored describes the feeling experienced by the trainees; boring describes its cause.","C":"Bored describes the feeling experienced by the trainees; boring describes its cause.","D":"This is not the adjective form for the role asked about: the person experiencing the feeling. Bored describes the feeling experienced by the trainees; boring describes its cause."}}},{"id":"91f7d986-38ad-55bc-af9d-8a9651d28a0c","topicSlug":"ed-ing-adjectives","level":"A2","prompt":"Describe the cause of feeling bored: The repetitive safety video was ____ for the trainees.","choices":[{"id":"A","text":"bores"},{"id":"B","text":"boring"},{"id":"C","text":"bored"},{"id":"D","text":"bore"}],"answerId":"B","hint":"The -ing form describes what produces the feeling. A person can also cause a feeling, so do not use a people-versus-things shortcut. Focus on **cause of feeling** in this question.","explanation":"Use boring for the situation that causes the trainees to feel bored.","keywords":[],"source":"seed","skill":"cause-of-feeling","contextKey":"emotion-1","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-ed-ing-adjectives"],"version":"foundations-2026-09-v2","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"adb6fa1f1446c2208aaded3640b034afc5ec9635e459d56fd4fb5a07a46a2812","teaching":{"steps":["Identify what the question tests: **cause of feeling**. The -ing form describes what produces the feeling. A person can also cause a feeling, so do not use a people-versus-things shortcut.","Use boring for the situation that causes the trainees to feel bored.","Choose **boring**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"This is not the adjective form for the role asked about: the cause of the feeling. Use boring for the situation that causes the trainees to feel bored.","B":"Use boring for the situation that causes the trainees to feel bored.","C":"This is not the adjective form for the role asked about: the cause of the feeling. Use boring for the situation that causes the trainees to feel bored.","D":"This is not the adjective form for the role asked about: the cause of the feeling. Use boring for the situation that causes the trainees to feel bored."}}},{"id":"06059d85-df0a-515f-a614-4a1c6b5a2f4d","topicSlug":"ed-ing-adjectives","level":"A2","prompt":"Choose the adjective pair from the “bore” family: The repetitive safety video was ____; the trainees felt ____.","choices":[{"id":"A","text":"bored / bored"},{"id":"B","text":"boring / boring"},{"id":"C","text":"boring / bored"},{"id":"D","text":"bored / boring"}],"answerId":"C","hint":"Read who experiences the emotion and what causes it. The two forms belong to the same adjective family but have different roles. Focus on **paired forms** in this question.","explanation":"The cause takes boring; the experiencers feel bored.","keywords":[],"source":"seed","skill":"paired-forms","contextKey":"emotion-1","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-ed-ing-adjectives"],"version":"foundations-2026-09-v2","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"2419b33a8cb2ae119de439bf0868006a3ce590736c1cc01ace3092206b0c9b0f","teaching":{"steps":["Identify what the question tests: **paired forms**. Read who experiences the emotion and what causes it. The two forms belong to the same adjective family but have different roles.","The cause takes boring; the experiencers feel bored.","Choose **boring / bored**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"At least one adjective in this pair assigns the wrong role: **-ed** normally describes the experiencer and **-ing** the cause. The cause takes boring; the experiencers feel bored.","B":"At least one adjective in this pair assigns the wrong role: **-ed** normally describes the experiencer and **-ing** the cause. The cause takes boring; the experiencers feel bored.","C":"The cause takes boring; the experiencers feel bored.","D":"At least one adjective in this pair assigns the wrong role: **-ed** normally describes the experiencer and **-ing** the cause. The cause takes boring; the experiencers feel bored."}}},{"id":"19110669-3645-57a1-a9b3-d036e3a3cf8f","topicSlug":"ed-ing-adjectives","lev